import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.Wk4ah3nE.js";const u=JSON.parse('{"title":"Host safety limits","description":"How host_limits prevents Proxmox VM Autoscale from pushing an already-saturated node further, and the edge cases in how the gate is applied.","frontmatter":{"title":"Host safety limits","description":"How host_limits prevents Proxmox VM Autoscale from pushing an already-saturated node further, and the edge cases in how the gate is applied.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/host-limits.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/host-limits.html"}],["meta",{"property":"og:title","content":"Host safety limits"}],["meta",{"property":"og:description","content":"How host_limits prevents Proxmox VM Autoscale from pushing an already-saturated node further, and the edge cases in how the gate is applied."}]]},"headers":[],"relativePath":"guide/host-limits.md","filePath":"guide/host-limits.md","lastUpdated":null}'),o={name:"guide/host-limits.md"};function n(r,e,h,l,d,c){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="host-safety-limits" tabindex="-1">Host safety limits <a class="header-anchor" href="#host-safety-limits" aria-label="Permalink to &quot;Host safety limits&quot;">​</a></h1><p>Autoscaling that ignores the hypervisor is a way to overcommit a node until everything on it suffers. <code>host_limits</code> is the guard against that.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">host_limits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_host_cpu_percent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">90</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_host_ram_percent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">90</span></span></code></pre></div><h2 id="how-the-check-works" tabindex="-1">How the check works <a class="header-anchor" href="#how-the-check-works" aria-label="Permalink to &quot;How the check works&quot;">​</a></h2><p>Before any VM on a node is evaluated, the service asks the node about itself:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pvesh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /nodes/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hostname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>and computes:</p><ul><li><strong>CPU</strong> — the <code>cpu</code> field (a fraction of total capacity) × 100.</li><li><strong>RAM</strong> — <code>memory.used / memory.total × 100</code>.</li></ul><p>If either exceeds its ceiling, that VM is skipped for this cycle:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] Host CPU usage exceeds maximum allowed limit: 94.10% &gt; 90%</span></span>\n<span class="line"><span>[WARNING] Host pve1 resources maxed out. Skipping scaling.</span></span></code></pre></div><p>The check runs <strong>per VM</strong>, not once per host, so a saturated node produces one warning pair per configured VM per cycle. Noisy, but it also means the reading is fresh for each decision.</p><h2 id="two-behaviours-worth-knowing" tabindex="-1">Two behaviours worth knowing <a class="header-anchor" href="#two-behaviours-worth-knowing" aria-label="Permalink to &quot;Two behaviours worth knowing&quot;">​</a></h2><h3 id="the-gate-blocks-scale-down-too" tabindex="-1">The gate blocks scale-down too <a class="header-anchor" href="#the-gate-blocks-scale-down-too" aria-label="Permalink to &quot;The gate blocks scale-down too&quot;">​</a></h3><p>The check sits before the usage read, so a node above its ceiling blocks <em>all</em> scaling on it — including shrinking an idle guest, which is exactly the action that would give the node back some headroom.</p><p>If your nodes routinely sit near the ceiling, consider raising <code>max_host_ram_percent</code>. Proxmox hosts with ZFS ARC or a large page cache legitimately run at high memory utilisation.</p><h3 id="used-is-not-total-free" tabindex="-1"><code>used</code> is not <code>total - free</code> <a class="header-anchor" href="#used-is-not-total-free" aria-label="Permalink to &quot;`used` is not `total - free`&quot;">​</a></h3><p>RAM is computed from the node&#39;s <code>used</code> field, which excludes reclaimable buff/cache and matches the Proxmox web UI. Before 0.1.1 the calculation used <code>free + cached</code> as available memory, so a node with a warm cache reported ~90% when the UI showed ~66% — and every scaling action on it was suppressed. If you are on an older version and nothing ever scales, that is very likely the cause.</p><h2 id="choosing-the-ceilings" tabindex="-1">Choosing the ceilings <a class="header-anchor" href="#choosing-the-ceilings" aria-label="Permalink to &quot;Choosing the ceilings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Reasonable range</th><th>Notes</th></tr></thead><tbody><tr><td><code>max_host_cpu_percent</code></td><td>80–90</td><td>Proxmox reports load across all cores; brief 100% spikes are normal, and the sample is instantaneous</td></tr><tr><td><code>max_host_ram_percent</code></td><td>85–95</td><td>With ZFS, ARC counts as used. Check <code>arc_summary</code> before deciding this is a real ceiling</td></tr></tbody></table><p>Both are required keys — there is no default. A missing <code>host_limits</code> section raises a <code>KeyError</code> on the first VM processed, surfacing as <code>Error processing VM ...</code> in the log.</p><h2 id="multi-node-behaviour" tabindex="-1">Multi-node behaviour <a class="header-anchor" href="#multi-node-behaviour" aria-label="Permalink to &quot;Multi-node behaviour&quot;">​</a></h2><p>Limits are global, not per host: the same two numbers apply to every node in <code>proxmox_hosts</code>. If one node is much smaller or much busier than the rest, you cannot express that today. The workaround is to run a second instance of the service with its own config file and its own systemd unit.</p><h2 id="what-is-not-checked" tabindex="-1">What is not checked <a class="header-anchor" href="#what-is-not-checked" aria-label="Permalink to &quot;What is not checked&quot;">​</a></h2><ul><li><strong>Storage.</strong> Disks are never scaled, so free space is not consulted. A full storage pool will not stop CPU or RAM scaling.</li><li><strong>Ballooning pressure across guests.</strong> Each VM is considered on its own; the service does not reason about total committed memory versus physical memory.</li><li><strong>Node quorum or cluster state.</strong> A node that has lost quorum still answers <code>pvesh get /nodes/.../status</code>, and scaling proceeds.</li><li><strong>Other consumers.</strong> Anything running on the node outside Proxmox&#39;s accounting is invisible.</li></ul>',24)])])}const g=s(o,[["render",n]]);export{u as __pageData,g as default};
